package com.example.storytv;
import android.app.Activity;import android.graphics.*;import android.os.Bundle;import android.speech.tts.TextToSpeech;import android.speech.tts.UtteranceProgressListener;import android.view.*;import java.util.*;
final class ReadingWords {
 final Activity activity;final View view;TextToSpeech tts;boolean ready=false,mode=false,spelling=false;int selected=0,token=0;String status="";String[] words=new String[0];
 ReadingWords(Activity a,View v,final Locale language){activity=a;view=v;tts=new TextToSpeech(a,new TextToSpeech.OnInitListener(){public void onInit(int code){if(code==TextToSpeech.SUCCESS){int result=tts.setLanguage(language);ready=result!=TextToSpeech.LANG_MISSING_DATA&&result!=TextToSpeech.LANG_NOT_SUPPORTED;}status=ready?"":"Voice unavailable for this language";view.invalidate();}});tts.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){}public void onError(String id){finish(id);}public void onDone(String id){finish(id);}void finish(final String id){activity.runOnUiThread(new Runnable(){public void run(){if(id.equals("spell-"+token)){spelling=false;status="";view.invalidate();}}});}});}
 void reset(){stop();mode=false;selected=0;words=new String[0];}void stop(){token++;spelling=false;if(tts!=null)tts.stop();status="";}void close(){stop();if(tts!=null)tts.shutdown();}
 void setText(String text){words=text.trim().split("\\s+");if(selected>=words.length)selected=0;}
 boolean key(int key){if(!mode){if(key==KeyEvent.KEYCODE_DPAD_UP){mode=true;selected=0;status="";view.invalidate();return true;}return false;}if(key==KeyEvent.KEYCODE_DPAD_DOWN||key==KeyEvent.KEYCODE_BACK){stop();mode=false;view.invalidate();return true;}if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){stop();if(words.length>0)selected=Math.max(0,Math.min(words.length-1,selected+(key==KeyEvent.KEYCODE_DPAD_RIGHT?1:-1)));view.invalidate();return true;}if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){speak();return true;}return true;}
 void speak(){if(words.length==0)return;if(!ready){status="Voice unavailable for this language";view.invalidate();return;}String word=WordLogic.clean(words[selected]);if(word.isEmpty())return;if(spelling){stop();status="Saying "+word;tts.speak(word,TextToSpeech.QUEUE_FLUSH,null,"word-"+token);view.invalidate();return;}stop();spelling=true;status="Spelling "+word+" - OK to hear the word";int current=token;String letters=WordLogic.letters(word);String[] parts=letters.isEmpty()?new String[0]:letters.split(" ");if(parts.length==0){spelling=false;return;}for(int i=0;i<parts.length;i++){tts.speak(parts[i],i==0?TextToSpeech.QUEUE_FLUSH:TextToSpeech.QUEUE_ADD,null,i==parts.length-1?"spell-"+current:"letter-"+current+"-"+i);if(i<parts.length-1)tts.playSilentUtterance(220,TextToSpeech.QUEUE_ADD,"pause-"+current+"-"+i);}tts.speak(word,TextToSpeech.QUEUE_ADD,null,"word-"+current);view.invalidate();}
 void draw(Canvas c,Paint p,String text,float center,float top,float maxWidth,int initialSize,int color){setText(text);p.setTypeface(Typeface.create("sans-serif-medium",0));p.setTextSize(initialSize);ArrayList<int[]> lines=new ArrayList<>();int start=0;float width=0;for(int i=0;i<words.length;i++){float part=p.measureText(words[i]);float space=i>start?p.measureText(" "):0;if(width+space+part>maxWidth&&i>start){lines.add(new int[]{start,i});start=i;width=part;}else width+=space+part;}lines.add(new int[]{start,words.length});float y=top;for(int[] line:lines){float lineWidth=0;for(int i=line[0];i<line[1];i++)lineWidth+=p.measureText(words[i])+(i>line[0]?p.measureText(" "):0);float x=center-lineWidth/2;for(int i=line[0];i<line[1];i++){float w=p.measureText(words[i]);if(mode&&i==selected){p.setColor(0xffffd77e);c.drawRoundRect(x-4,y-initialSize,x+w+4,y+8,8,8,p);}p.setColor(color);p.setTextAlign(Paint.Align.LEFT);c.drawText(words[i],x,y,p);x+=w+p.measureText(" ");}y+=initialSize+8;}p.setTextAlign(Paint.Align.CENTER);p.setTextSize(18);p.setColor(0xff567a7b);String hint=mode?(status.isEmpty()?"LEFT / RIGHT: choose word    OK: hear spelling    DOWN: done":status):"UP: choose a word";c.drawText(hint,center,700,p);}
}
